INSERT INTO cmd_command_type VALUES('quote_starship_charter','Quote starship charter'),('accept_starship_charter','Accept starship charter'),('complete_starship_charter','Complete starship charter');
INSERT INTO cmd_domain_event_type VALUES('starship_charter_quoted','Starship charter quoted'),('starship_charter_accepted','Starship charter accepted'),('starship_charter_completed','Starship charter completed');
CREATE TABLE cmd_starship_charter_quote_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),charter_quote_id bigint NOT NULL UNIQUE,ship_id bigint NOT NULL,billing_blocks integer NOT NULL CHECK(billing_blocks>0),quoted_price_credits bigint NOT NULL CHECK(quoted_price_credits>=0),FOREIGN KEY(charter_quote_id,campaign_id) REFERENCES journey_starship_charter_quote_receipt(charter_quote_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id));
CREATE TABLE cmd_starship_charter_acceptance_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),charter_contract_id bigint NOT NULL UNIQUE,charter_quote_id bigint NOT NULL UNIQUE,journey_id bigint NOT NULL UNIQUE,ship_id bigint NOT NULL,promised_payment_credits bigint NOT NULL CHECK(promised_payment_credits>=0),FOREIGN KEY(charter_contract_id,campaign_id) REFERENCES journey_starship_charter_contract(charter_contract_id,campaign_id),FOREIGN KEY(charter_quote_id,campaign_id) REFERENCES journey_starship_charter_quote_receipt(charter_quote_id,campaign_id),FOREIGN KEY(journey_id,campaign_id) REFERENCES journey_journey(journey_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id));
CREATE TABLE cmd_starship_charter_completion_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),charter_contract_id bigint NOT NULL UNIQUE,actor_id bigint NOT NULL,financial_transaction_id bigint NOT NULL UNIQUE,balance_after_minor bigint NOT NULL,FOREIGN KEY(charter_contract_id,campaign_id) REFERENCES journey_starship_charter_contract(charter_contract_id,campaign_id),FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(financial_transaction_id,campaign_id) REFERENCES fin_transaction(transaction_id,campaign_id));
